static void Texture(string path,bool normal,bool linear){var t=(TextureImporter)AssetImporter.GetAtPath(path);t.textureType=normal?TextureImporterType.NormalMap:TextureImporterType.Default;t.sRGBTexture=!linear&&!normal;t.maxTextureSize=2048;t.mipmapEnabled=true;t.wrapModeU=TextureWrapMode.Repeat;t.wrapModeV=TextureWrapMode.Clamp;t.textureCompression=TextureImporterCompression.CompressedHQ;t.alphaSource=TextureImporterAlphaSource.FromInput;t.SaveAndReimport();}
public static string Main(){if(EditorApplication.isPlaying)throw new Exception("Edit mode required");var scene=SceneManager.GetActiveScene();if(scene.path!="Assets/Afrer_Seconds/01.Scenes/Stage/Level_B5_Isolation.unity")throw new Exception("Expected active B5 scene; preserve other open scenes");Directory.CreateDirectory(R+"/Backup");if(!File.Exists(R+"/Backup/Level_B5_Isolation.unity")){File.Copy(scene.path,R+"/Backup/Level_B5_Isolation.unity");File.Copy(scene.path+".meta",R+"/Backup/Level_B5_Isolation.unity.meta");}if(scene.isDirty){if(!EditorSceneManager.SaveScene(scene))throw new Exception("Could not preserve current changes");File.Copy(scene.path,R+"/Backup/UserCurrentBeforePilot.unity",true);}var all=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var before=all.SelectMany(t=>t.GetComponents<Collider>()).Select(CR).ToArray();File.WriteAllText(R+"/colliders_before.json",JsonConvert.SerializeObject(before,Formatting.Indented));
Render("NorthWall_before",new Vector3(-2.9f,1.75f,5.3f),new Vector3(-3.5f,1.55f,1.88f));Render("CellWall_before",new Vector3(.1f,1.65f,9.4f),new Vector3(1.5f,1.3f,11.1f));
Directory.CreateDirectory(Root+"/Materials");Directory.CreateDirectory(Root+"/Meshes");AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);int materialsBefore=Directory.GetFiles(Application.dataPath,"*.mat",SearchOption.AllDirectories).Length;string baseMap=Root+"/Textures/FacilityWall_BaseColor.png",normalMap=Root+"/Textures/FacilityWall_Normal.png",mask=Root+"/Textures/FacilityWall_Mask.png";Texture(baseMap,false,false);Texture(normalMap,true,true);Texture(mask,false,true);string matPath=Root+"/Materials/FacilityWall_PaintedConcrete.mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(matPath);if(!mat){mat=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(mat,matPath);}mat.SetColor("_BaseColor",Color.white);mat.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(baseMap));mat.SetTexture("_BumpMap",AssetDatabase.LoadAssetAtPath<Texture2D>(normalMap));mat.SetFloat("_BumpScale",.45f);mat.EnableKeyword("_NORMALMAP");mat.SetTexture("_MetallicGlossMap",AssetDatabase.LoadAssetAtPath<Texture2D>(mask));mat.SetFloat("_Metallic",1);mat.SetFloat("_Smoothness",1);mat.EnableKeyword("_METALLICSPECGLOSSMAP");mat.SetTexture("_OcclusionMap",AssetDatabase.LoadAssetAtPath<Texture2D>(mask));mat.SetFloat("_OcclusionStrength",.6f);mat.EnableKeyword("_OCCLUSIONMAP");mat.enableInstancing=true;EditorUtility.SetDirty(mat);
var targets=all.Where(t=>P(t).StartsWith("B5_Level_V0.01/Room01_Isolation/Geometry/")&&(t.name.StartsWith("Wall_")||t.name.StartsWith("Cell_Wall_"))).Select(t=>t.GetComponent<MeshRenderer>()).Where(m=>m&&m.enabled).ToArray();if(targets.Length!=7)throw new Exception("Expected 7 pilot walls, found "+targets.Length);var records=new List<object>();foreach(var renderer in targets){var filter=renderer.GetComponent<MeshFilter>();var source=filter.sharedMesh;var mesh=UnityEngine.Object.Instantiate(source);mesh.name=renderer.name+"_MetricUV";var vertices=mesh.vertices;var normals=mesh.normals;var uv=new Vector2[vertices.Length];var t=renderer.transform;for(int i=0;i<vertices.Length;i++){var w=t.TransformPoint(vertices[i]);var n=t.TransformDirection(normals[i]).normalized;float u=Mathf.Abs(n.x)>.5f?w.z/2:w.x/2;float v=Mathf.Abs(n.y)>.5f?.85f:w.y/4;uv[i]=new Vector2(u,v);}mesh.uv=uv;mesh.RecalculateTangents();if(!source.vertices.SequenceEqual(mesh.vertices)||!source.triangles.SequenceEqual(mesh.triangles)||!source.normals.SequenceEqual(mesh.normals))throw new Exception("Geometry changed");string meshPath=Root+"/Meshes/"+mesh.name+".asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(meshPath);if(!old)AssetDatabase.CreateAsset(mesh,meshPath);else{EditorUtility.CopySerialized(mesh,old);UnityEngine.Object.DestroyImmediate(mesh);mesh=old;}string previous=AssetDatabase.GetAssetPath(renderer.sharedMaterial);filter.sharedMesh=mesh;renderer.sharedMaterial=mat;EditorUtility.SetDirty(filter);EditorUtility.SetDirty(renderer);records.Add(new{path=P(t),previousMaterial=previous,material=matPath,mesh=meshPath,geometryPreserved=true,uvVertices=uv.Length,triangles=mesh.triangles.Length/3});}
var after=all.SelectMany(t=>t.GetComponents<Collider>()).Select(CR).ToArray();bool same=JToken.DeepEquals(JToken.Parse(JsonConvert.SerializeObject(before)),JToken.Parse(JsonConvert.SerializeObject(after)));if(!same)throw new Exception("Colliders changed");AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);Render("NorthWall_after",new Vector3(-2.9f,1.75f,5.3f),new Vector3(-3.5f,1.55f,1.88f));Render("CellWall_after",new Vector3(.1f,1.65f,9.4f),new Vector3(1.5f,1.3f,11.1f));int materialDelta=Directory.GetFiles(Application.dataPath,"*.mat",SearchOption.AllDirectories).Length-materialsBefore;if(materialDelta>1)throw new Exception("More than one material added");File.WriteAllText(R+"/application_facts.json",JsonConvert.SerializeObject(new{scene=scene.path,sharedMaterial=matPath,newMaterials=materialDelta,uniquePilotMaterials=targets.Select(r=>r.sharedMaterial).Distinct().Count(),walls=records,existingCollidersPreserved=same,texelDensity=512,tileMetres=new[]{2,4}},Formatting.Indented));return "Applied one shared PBR material to 7 B5 general walls; geometry and colliders preserved";
